const fs = require('fs');

const raw = fs.readFileSync(0, 'utf8').split('\n').map(l => l.replace(/\r/g, ''));

const first = (raw[0] || '').trim().split(/\s+/);
const K = parseInt(first[0], 10);
const N = parseInt(first[1], 10);

// Remove qualquer espaço em branco (funciona tanto com caracteres separados por espaço quanto colados)
const alphabet = (raw[1] || '').replace(/\s/g, '');
const message = (raw[2] || '').replace(/\s/g, '').slice(0, N);

const allowed = new Set(alphabet);

let ok = true;
for (let i = 0; i < message.length && ok; i++) {
    if (!allowed.has(message[i])) ok = false;
}

console.log(ok ? 'S' : 'N');
